C++<pre><code>template &lt;typename QAQ&gt;
class MPMCQueue {
   public:
    bool push(QAQ value) {
        {
            std::lock_guard&lt;std::mutex&gt; lock(_mutex);
            if (_closed)
                return false;
            _queue.push(std::move(value));
        }

        _cv.notify_one();
        return true;
    }

    bool pop(QAQ&amp; value) {
        std::unique_lock&lt;std::mutex&gt; lock(_mutex);

        _cv.wait(lock, [this] { return !_queue.empty() || _closed; });

        if (_queue.empty() &amp;&amp; _closed)
            return false;

        value = std::move(_queue.front());
        _queue.pop();
        return true;
    }

    void close() {
        {
            std::lock_guard&lt;std::mutex&gt; lock(_mutex);
            _closed = true;
        }
        _cv.notify_all();
    }

   private:
    std::queue&lt;QAQ&gt; _queue;
    std::mutex _mutex;
    std::condition_variable _cv;
    bool _closed = false;
};
</code></pre>

C++<pre><code>struct Node {
    Node* next;
};

class Stack {  // 链式栈
   public:
    void push(Node* node) {
        std::lock_guard&lt;std::mutex&gt; lock(_mutex);
        node-&gt;next = _head;
        _head = node;
    }

    Node* pop() {
        std::lock_guard&lt;std::mutex&gt; lock(_mutex);
        if (!_head)
            return nullptr;
        Node* node = _head;
        _head = _head-&gt;next;
        return node;
    }

   private:
    Node* _head{nullptr};
    std::mutex _mutex;
};

class MemoryPool {
   public:
    MemoryPool(size_t blockSize, size_t count) : _blockSize(blockSize), _memory(blockSize * count) { init(); }

    void* allocate() { return _stack.pop(); }

    void deallocate(void* ptr) { _stack.push(static_cast&lt;Node*&gt;(ptr)); }

   private:
    void init() {
        auto* start = _memory.data();
        for (size_t i = 0; i &lt; _memory.size(); i += _blockSize) {
            Node* node = reinterpret_cast&lt;Node*&gt;(start + i);
            _stack.push(node);
        }
    }

   private:
    size_t _blockSize;
    std::vector&lt;std::byte&gt; _memory;
    Stack _stack;
};
</code></pre>

C++<pre><code>template &lt;typename QAQ, std::size_t SIZE&gt;
class SPSCQueue {
   public:
    bool push(const QAQ&amp; value) {
        auto tail = _tail.load(std::memory_order_relaxed);

        if (tail - _head.load(std::memory_order_acquire) &gt;= SIZE)
            return false;  // full
        _queue[tail % SIZE] = value;

        _tail.store(tail + 1, std::memory_order_release);
        return true;
    }

    bool pop(QAQ&amp; value) {
        auto head = _head.load(std::memory_order_relaxed);

        if (head == _tail.load(std::memory_order_acquire))
            return false;  // empty
        value = _queue[head % SIZE];

        _head.store(head + 1, std::memory_order_release);
        return true;
    }

   private:
    std::array&lt;QAQ, SIZE&gt; _queue;
    alignas(64) std::atomic&lt;std::size_t&gt; _head{0};  // 内存对齐以独享 cache line
    alignas(64) std::atomic&lt;std::size_t&gt; _tail{0};
};
</code></pre>

C++<pre><code>class ThreadPool {
   public:
    explicit ThreadPool(size_t threadNum) {
        while (threadNum--)  // 创建线程
            _workers.emplace_back([this] {
                std::function&lt;void()&gt; task;
                while (_tasks.pop(task))  // 取不到任务会阻塞在 pop
                    task();
            });
    }

    bool submit(std::function&lt;void()&gt; task) { return _tasks.push(std::move(task)); }

    ~ThreadPool() {
        _tasks.close();                // 不再接收新任务
        for (auto&amp; worker : _workers)  // 等待所有线程退出
            if (worker.joinable())
                worker.join();
    }

   private:
    MPMCQueue&lt;std::function&lt;void()&gt;&gt; _tasks;
    std::vector&lt;std::thread&gt; _workers;
};
</code></pre>

